function overlay(){let d=server.current;for(const ops of pending.current)d=apply(d,ops);render(d)}
async function flush(){if(sending.current||!pRef.current||!pending.current.length)return;sending.current=true;const p=pRef.current;setStatus('Сохранение…');try{while(pending.current.length&&pRef.current?.id===p.id){const ops=pending.current[0];const v=await api(p,{ops,name:nameRef.current});if(pRef.current?.id!==p.id)break;pending.current.shift();saveQueue();if(v.revision>=rev.current){server.current=v.document;rev.current=v.revision}overlay()}setStatus('Все изменения сохранены')}catch(e:any){if(e.status===401){saveQueue();setStatus('Нужно войти в аккаунт')}else if(e.status&&e.status<500){pending.current.shift();saveQueue();overlay();notify(e.message);if(e.status===403)setRole('viewer')}else setStatus('Нет связи · изменения сохранены на устройстве')}finally{sending.current=false}}
