async function open(p:Project){if(pending.current.length){notify('Дождитесь сохранения текущих изменений');return}loading.current=true;setConnecting(p);setOpenError('');setStatus('Подключение…');try{const v=await api(p);pRef.current=p;setProject(p);rev.current=v.revision;server.current=v.document;setRole(v.role);setPeople(v.people||[]);try{pending.current=JSON.parse(localStorage.getItem(outboxKey(p.id))||'[]')}catch{pending.current=[]}overlay();undo.current=[];redo.current=[];setSelection(null);location.hash=new URLSearchParams({p:p.id,k:p.key}).toString();const ps=JSON.parse(localStorage.getItem(projectStorageKey)||'[]');const prior=ps.find((x:Project)=>x.id===p.id);const rank:Record<string,number>={owner:3,editor:2,viewer:1};const keep=prior&&(rank[prior.role||'']||0)>(rank[v.role]||0)?prior:{...p,role:v.role};persistProjects([{...keep,title:v.document.title},...ps.filter((x:Project)=>x.id!==p.id)].slice(0,40));setStatus(v.role==='viewer'?'Режим просмотра':'Все изменения сохранены');setConnecting(null);setModal('');if(account)void account.onOpened({...p,title:v.document.title,role:v.role}).catch(()=>notify('Схема открыта, но не добавлена в кабинет. Вернитесь в кабинет и повторите попытку.'));void flush()}catch(e:any){setStatus('Не удалось открыть проект');setOpenError(e.message);notify(e.message)}finally{loading.current=false}}
useEffect(()=>{const n=account?.user.name||localStorage.getItem('flow-name')||'Инженер';setName(n);nameRef.current=n;session.current=uid();try{setProjects(JSON.parse(localStorage.getItem(projectStorageKey)||'[]'));setCustom(JSON.parse(localStorage.getItem('flow-library')||'[]'))}catch{}const h=new URLSearchParams(location.hash.slice(1));if(h.get('p')&&h.get('k'))void open({id:h.get('p')!,key:h.get('k')!,title:''});else {const d=example();server.current=d;render(d)}setReady(true);const poll=singleFlight(async()=>{const p=pRef.current;if(!p||sending.current||loading.current||drag.current)return;try{const v=await api(p,undefined,rev.current);if(pRef.current?.id!==p.id)return;if(!v.unchanged&&v.revision>=rev.current){server.current=v.document;rev.current=v.revision;overlay()}setRole(v.role);setPeople(v.people||[]);if(pending.current.length)void flush();else setStatus(v.role==='viewer'?'Режим просмотра':'Все изменения сохранены')}catch(e:any){setStatus(e.status===403?'Доступ отозван':'Нет связи · повторное подключение…');if(e.status===403)setRole('viewer')}});const t=setInterval(()=>void poll(),SYNC_MS);const heartbeat=singleFlight(async()=>{if(pRef.current)await api(pRef.current,{action:'presence',session:session.current,name:nameRef.current}).catch(()=>{})});const hbeat=setInterval(()=>void heartbeat(),HEARTBEAT_MS);const close=(e:BeforeUnloadEvent)=>{if(pending.current.length){e.preventDefault();e.returnValue=''}};window.addEventListener('beforeunload',close);return()=>{clearInterval(t);clearInterval(hbeat);window.removeEventListener('beforeunload',close)}},[]);
async function create(d=docRef.current){if(pending.current.length){notify('Сначала дождитесь сохранения');return}setStatus('Создаём общий проект…');try{if(account){const p=await account.onCreate(d);await open(p);notify('Проект сохранён в личном кабинете');return}const r=await fetch(apiUrl('/api/projects',API_ORIGIN),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({document:d})});const v:any=await r.json();if(!r.ok)throw new Error(v.error);await open({id:v.id,key:v.key,title:d.title});notify('Общий проект создан. Теперь можно поделиться ссылкой.')}catch(e:any){notify(e.message);setStatus('Ошибка создания проекта')}}
