function escape(s:string){return s.replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]!))}
function svg(){const routeBounds=edges.flatMap(e=>geometry(e).bounds);const minX=Math.min(0,...nodes.map(n=>n.x),...routeBounds.map(p=>p.x))-45,minY=Math.min(0,...nodes.map(n=>n.y),...routeBounds.map(p=>p.y))-70,w=Math.max(1000,...nodes.map(n=>n.x+deviceWidth(n)+40),...routeBounds.map(p=>p.x+60))-minX,h=Math.max(650,...nodes.map(n=>n.y+height(n)+50),...routeBounds.map(p=>p.y+60))-minY;let s=`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="${minX} ${minY} ${w} ${h}"><rect x="${minX}" y="${minY}" width="${w}" height="${h}" fill="#f5f7fa"/><text x="${minX+30}" y="${minY+35}" font-family="Arial" font-size="20" fill="#16243b">${escape(doc.title)} · RUHUB Flow</text>`;for(const e of edges){s+=`<path d="${path(e)}" fill="none" stroke="#f5f7fa" stroke-width="7" stroke-linejoin="round"/><path d="${path(e)}" fill="none" stroke="${cableColor(e)}" stroke-width="3" stroke-linejoin="round"/>`;const center=geometry(e).label;if(e.label)s+=`<text x="${center.x}" y="${center.y-8}" font-family="Arial" font-size="11" fill="#52647b">${escape(e.label)}</text>`}for(const n of nodes){s+=`<rect x="${n.x}" y="${n.y}" width="${deviceWidth(n)}" height="${height(n)}" rx="10" fill="white" stroke="#ced8e5"/><rect x="${n.x}" y="${n.y}" width="${deviceWidth(n)}" height="5" rx="2" fill="${n.color}"/><text x="${n.x+16}" y="${n.y+27}" font-family="Arial" font-size="10" fill="#63748a">${escape(n.brand)}</text><text x="${n.x+16}" y="${n.y+48}" font-family="Arial" font-size="13" fill="#15243d">${escape(n.label.slice(0,32))}</text>`;for(const p of visiblePorts(n)){const a=point(n,p.id);s+=`<circle cx="${a.x}" cy="${a.y}" r="4" fill="${colors[p.type]}"/><text x="${a.x+(p.dir==='in'?12:-12)}" y="${a.y+4}" text-anchor="${p.dir==='in'?'start':'end'}" font-size="10" font-family="Arial" fill="#52647b">${escape(p.label)}</text>`}}return {text:s+'</svg>',w,h}}
async function exportPNG(){const s=svg(),url=URL.createObjectURL(new Blob([s.text],{type:'image/svg+xml'}));const img=new Image();img.onload=()=>{const c=document.createElement('canvas');const scale=Math.min(2,8192/Math.max(s.w,s.h));c.width=s.w*scale;c.height=s.h*scale;const ctx=c.getContext('2d')!;ctx.scale(scale,scale);ctx.drawImage(img,0,0);c.toBlob(b=>{if(b){const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=doc.title+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}},'image/png');URL.revokeObjectURL(url)};img.onerror=()=>notify('Не удалось создать PNG. Используйте SVG.');img.src=url}
async function importFile(e:React.ChangeEvent<HTMLInputElement>){const f=e.target.files?.[0];if(!f)return;try{const d=JSON.parse(await f.text());if(typeof d.title!=='string'||!d.nodes||!d.edges||Object.keys(d.nodes).length>500)throw Error();for(const n of Object.values(d.nodes) as any[])if(!n.id||!Array.isArray(n.ports)||!Number.isFinite(n.x)||!Number.isFinite(n.y))throw Error();await create(d)}catch{notify('Неверный файл проекта')}e.target.value=''}
useEffect(()=>{if(ready)requestAnimationFrame(()=>fit())},[ready]);
