{nodes.map(n=>{const Icon=iconFor(n.model),ps=visiblePorts(n);return <div className={'node '+(selection?.id===n.id?'selected':'')} key={n.id} style={{left:n.x,top:n.y,width:deviceWidth(n),height:height(n),'--accent':n.color,'--port-height':portStep(n)+'px'} as any} onPointerDown={e=>{e.stopPropagation();if(e.button!==0)return;setSelection({kind:'node',id:n.id});if(tool==='hand'){drag.current={pointerId:e.pointerId,pointerType:e.pointerType,kind:'pan',sx:e.clientX,sy:e.clientY,x:pan.x,y:pan.y};scene.current!.setPointerCapture(e.pointerId);return}if(editable){drag.current={pointerId:e.pointerId,pointerType:e.pointerType,kind:'node',id:n.id,sx:e.clientX,sy:e.clientY,x:n.x,y:n.y};scene.current!.setPointerCapture(e.pointerId)}}}><div className="node-head"><span className="node-icon"><Icon size={17}/></span><div><small>{n.brand}</small><strong title={n.label}>{n.label}</strong></div><span className="node-id">{nodes.indexOf(n)+1<10?'0':''}{nodes.indexOf(n)+1}</span></div><div className="node-ports"><div>{ps.filter(p=>p.dir==='in').map(p=><button key={p.id} title={p.type+' · '+connectorOf(p)+' · '+p.label} data-node-port data-port-node={n.id} data-port-id={p.id} className={'port in '+portClass(n,p)} aria-disabled={portClass(n,p)==='incompatible'} onPointerDown={e=>beginPortGesture(e,n,p)} onClick={()=>clickPort(n,p)}><i style={{background:colors[p.type],borderColor:colors[p.type]}}/>{p.label}</button>)}</div><div>{ps.filter(p=>p.dir==='out').map(p=><button key={p.id} title={p.type+' · '+connectorOf(p)+' · '+p.label} data-node-port data-port-node={n.id} data-port-id={p.id} className={'port out '+portClass(n,p)} aria-disabled={portClass(n,p)==='incompatible'} onPointerDown={e=>beginPortGesture(e,n,p)} onClick={()=>clickPort(n,p)}>{p.label}<i style={{background:colors[p.type],borderColor:colors[p.type]}}/></button>)}</div></div>{n.ports.length>8&&<button className="expand-ports" onPointerDown={e=>e.stopPropagation()} onClick={()=>setExpanded(x=>x.includes(n.id)?x.filter(k=>k!==n.id):[...x,n.id])}>{expanded.includes(n.id)?'Свернуть порты':`Все порты (${n.ports.length})`}<ChevronDown size={12}/></button>}{editable&&(['se'] as const).map(h=><button key={h} className={'resize-grip resize-'+h} style={touchInput?{width:32/zoom,height:32/zoom,right:-16/zoom,bottom:-16/zoom}:undefined} aria-label={'Изменить размер: '+({n:'верх',s:'низ',e:'справа',w:'слева',ne:'правый верхний угол',nw:'левый верхний угол',se:'правый нижний угол',sw:'левый нижний угол'}[h])} title="Потяните, чтобы изменить размер" onPointerDown={e=>beginResize(e,n,h)} onClick={e=>e.stopPropagation()}/>)}</div>})}
